{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Studies were included if they compared pregnancy outcomes between the COVID-­ 19 pandemic period and pre-­ pandemic time periods and reported on any of the outcomes of interest. We excluded studies that only reported outcomes of pregnant women with COVID-­ 19. ... The search strategy used a combination of the MeSH terms 'preterm' or 'stillbirth' AND 'Covid19' or 'SARS-­ CoV-­ 2' and included any type of study design published in the English language",
      "reason": "Eligibility specifies the key comparison (pandemic vs pre-pandemic pregnancy outcomes) and an exclusion (studies reporting only women infected with COVID-19), and notes eligible study designs and English language. However, relevant question-framework components such as specific settings and follow-up requirements are not clearly specified in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "We searched PubMed and Embase databases, reference lists of included articles, and personal files for studies published up to August 14, 2021. ... included any type of study design published in the English language",
      "reason": "The dissemination timeframe (published up to August 14, 2021) and language (English) are specified. The retrieved evidence does not explicitly report publication/report status criteria (e.g., published vs unpublished) or other report-characteristic eligibility items."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_13",
      "quote": null,
      "reason": "No explicit statement is provided distinguishing exclusions due to outcomes not being measured versus outcomes not being reported. Although the PRISMA flow figure lists exclusion reasons (e.g., 'No outcome data'), the retrieved evidence does not make the required distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "Post-­hoc subgroup analyses were conducted for the two primary outcomes after dividing studies into single-­ center (or selected hospitals/centers in an area), regional (statewide or province-­ wide) or national in scope.",
      "reason": "The retrieved evidence specifies how studies are grouped for subgroup analyses (single-center, regional, national). However, it does not explicitly link these groups to specific comparisons defined in the review objectives within the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "For one study conducted in the Netherlands by Been et al, ... with several different comparisons, making it difficult to select one comparison that aligned well with the other studies; we, therefore, included this study in the systematic review but not in meta-­ analyses.",
      "reason": "A rationale is provided for a notable restriction on eligibility for quantitative synthesis (including a study in the review but not meta-analyses due to difficulty selecting an aligned comparison)."
    }
  ],
  "confidence": 62
}

